import{NextRequest,NextResponse}from"next/server";import{z}from"zod";import{db}from"@/lib/db";import{requireApiUser}from"@/lib/auth";import{apiError,assertSameOrigin,HttpError}from"@/lib/http";import{recordApprovedPayment}from"@/domain/payments";import{audit}from"@/lib/audit";
const schema=z.object({clientId:z.string(),serviceId:z.string(),amount:z.coerce.number().positive(),effectiveAt:z.coerce.date(),method:z.enum(["BANK_TRANSFER","CASH","OTHER"]),reference:z.string().max(200).optional(),notes:z.string().max(2000).optional()});
export async function POST(req:NextRequest){try{assertSameOrigin(req);const user=await requireApiUser(req,"payments.external.confirm");const input=schema.parse(await req.json());const service=await db.service.findUnique({where:{id:input.serviceId},include:{subscriptions:{where:{status:"AUTHORIZED"}},payments:{where:{status:{in:["PENDING","APPROVED"]}},orderBy:{createdAt:"desc"},take:5}}});if(!service||service.clientId!==input.clientId)throw new HttpError(404,"Servicio inválido");const end=new Date(input.effectiveAt);end.setMonth(end.getMonth()+1);const scheduled=service.subscriptions.some(s=>s.nextBillingAt&&s.nextBillingAt>=input.effectiveAt&&s.nextBillingAt<end);const overlapping=service.payments.some(p=>p.periodStart&&p.periodEnd&&p.periodStart<end&&p.periodEnd>input.effectiveAt);if(scheduled||overlapping){await db.incident.create({data:{serviceId:service.id,code:"EXTERNAL_PAYMENT_DUPLICATION_RISK",severity:"CRITICAL",title:"Pago externo no confirmado",detail:"Existe un cobro de Mercado Pago programado o un período ya cubierto. Conciliá antes de confirmar."}});throw new HttpError(409,"Existe riesgo de cobro duplicado. Se creó una incidencia para conciliación.","duplicate_risk")}
const key=`external:${service.id}:${input.effectiveAt.toISOString().slice(0,10)}`;const payment=await db.$transaction(tx=>recordApprovedPayment(tx,{clientId:input.clientId,serviceId:input.serviceId,provider:"EXTERNAL",idempotencyKey:key,method:input.method,grossAmount:input.amount,netAmount:input.amount,effectiveAt:input.effectiveAt,externalReference:input.reference,notes:input.notes,confirmedById:user.id}));await audit({actorId:user.id,action:"confirm_external",module:"payments",recordType:"Payment",recordId:payment.id,after:payment});return NextResponse.json(payment,{status:201})}catch(e){return apiError(e)}}
